<script setup>
import RFB from '@novnc/novnc'
</script>
<template>
  <div ref="vncContainer" class="vnc-container w-full h-full"
    @focus="syncHostClipboardToNoVNC"
  ></div>
</template>
<script>
export default {
  name: 'NoVNCViewer',
  props: {
    path: { type: String, default: '' },
    password: { type: String, default: 'password' },
    /**
     * How the framebuffer follows the panel:
     *  - `scale`  keep the desktop size and let CSS scale the image
     *  - `remote` ask the server for the container size (SetDesktopSize)
     * `null` keeps whatever the user configured in the UI settings.
     */
    resizeMode: { type: String, default: null },
    /** Debounce before asking the server for a new size. */
    resizeDebounce: { type: Number, default: 400 }
  },
  emits: ['connect', 'disconnect'],
  data() {
    return {
      rfb: null,
      noVNClipboard: null,
      observer: null,
      resizeTimer: null
    };
  },
  mounted() {
    window.$noVNC = this
    this.startObserving()
    this.connect()
  },
  computed: {
    canvas () {
      return this.$el.querySelector('canvas')
    },
    resizeType () {
      return this.resizeMode || this.$ui?.noVNCSettings?.resize || 'scale'
    }
  },
  watch: {
    resizeType () {
      this.connect()
    }
  },
  beforeDestroy() {
    this.stopObserving()
    this.disconnect()
  },
  beforeUnmount() {
    this.stopObserving()
    this.disconnect()
  },
  methods: {
    disconnect () {
      try {
        this.rfb?.disconnect()
      } catch (error) {
        // already disconnected
      }
      this.rfb = null
    },
    startObserving () {
      if (this.observer || typeof ResizeObserver === 'undefined') return
      // Remote resize is driven by the panel size: the server is asked again
      // when the box settles, so dragging a splitter does not flood it.
      this.observer = new ResizeObserver(() => this.onContainerResize())
      this.observer.observe(this.$refs.vncContainer)
    },
    stopObserving () {
      if (this.resizeTimer) {
        window.clearTimeout(this.resizeTimer)
        this.resizeTimer = null
      }
      if (this.observer) {
        this.observer.disconnect()
        this.observer = null
      }
    },
    containerSize () {
      const element = this.$refs.vncContainer
      if (!element) return null
      const width = element.clientWidth
      const height = element.clientHeight
      if (!width || !height) return null
      return { width, height }
    },
    onContainerResize () {
      if (this.resizeType !== 'remote') return
      if (this.resizeTimer) window.clearTimeout(this.resizeTimer)
      this.resizeTimer = window.setTimeout(() => {
        this.resizeTimer = null
        this.requestRemoteResize()
      }, Math.max(100, this.resizeDebounce || 400))
    },
    applyResizeMode () {
      if (!this.rfb) return
      if (this.resizeType === 'scale') {
        this.rfb.clipViewport = false
        this.rfb.resizeSession = false
        this.rfb.scaleViewport = true
      } else if (this.resizeType === 'remote') {
        this.rfb.scaleViewport = false
        this.rfb.clipViewport = true
        this.rfb.resizeSession = true
      }
    },
    /**
     * Ask the server for the container size (RFB SetDesktopSize).
     *
     * noVNC re-arms the request when `resizeSession` goes from false to true,
     * which is the only public way to force a fresh SetDesktopSize.
     */
    requestRemoteResize () {
      if (!this.rfb || this.resizeType !== 'remote') return
      if (!this.containerSize()) return
      try {
        this.rfb.resizeSession = false
        this.rfb.clipViewport = true
        this.rfb.resizeSession = true
      } catch (error) {
        console.warn('NoVNC remote resize failed', error)
      }
    },
    connect () {
      this.rfb?.disconnect()

      const protocol = window.location.protocol.includes("https") ? "wss": "ws"
      const url = `${protocol}://${window.location.host}${this.path}`
      const options = {
        credentials: {
          password: this.password || "password"
        },
      };

      this.rfb = new RFB(this.$refs.vncContainer, url, options);

      this.applyResizeMode()

      this.rfb.addEventListener('connect', () => {
        console.log('Connected to the NoVNC server');
        this.$emit('connect');
        // The framebuffer can be bigger than the panel: in remote mode the
        // server is asked to follow the container as soon as it connects.
        if (this.resizeType === 'remote') this.requestRemoteResize()
      });

      this.rfb.addEventListener('disconnect', () => {
        console.log('Disconnected from the NoVNC server');
        this.$emit('disconnect');
      });

      this.rfb.addEventListener('clipboard', (event) => {
        this.noVNClipboard = event.detail.text
        this.syncNoVNCToHostClipboard()
      });

      if (this.canvas) {
        this.canvas.onfocus = this.syncHostClipboardToNoVNC.bind(this)
      }
    },
    syncHostClipboardToNoVNC () {
      navigator.clipboard.readText().then(text => {
        if (this.noVNClipboard != text) {
          this.rfb.clipboardPasteFrom(text);
          console.log('Clipboard synced HOST->NoVNC')
        }
        this.noVNClipboard = text
      })
    },
    syncNoVNCToHostClipboard() {
      navigator.clipboard.writeText(this.noVNClipboard)
        .then(() => console.log('Clipboard synced NoVNC->HOST', this.noVNClipboard))
        .catch(err => console.error('Could not sync NoVNC->HOST clipboard:', err));

    }
  }
};
</script>
